#!/usr/bin/env node
// ---------------------------------------------------------------------------
// verify-theme-sync.mjs — guard against FOUC bootstrap drift
//
// packages/theme/bootstrap.js is the canonical source. The apps/console/public and
// apps/management/public copies are generated by scripts/sync-theme-bootstrap.mjs.
// This script verifies each copy is byte-identical to the source AND that the
// source contains the expected behavior markers — so any hand-edit to a copy,
// or an edit to the source without a re-sync, fails the check
// (scripts/dev/test.sh runs it in every quick gate).
//
// Usage:
//   node scripts/verify-theme-sync.mjs
//   pnpm verify:theme-sync
// ---------------------------------------------------------------------------

import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const __filename = fileURLToPath(import.meta.url)
const ROOT = dirname(dirname(dirname(dirname(__filename))))

const SOURCE = join(ROOT, 'packages/theme/bootstrap.js')
const COPIES = [
  join(ROOT, 'apps/console/public/theme-bootstrap.js'),
  join(ROOT, 'apps/management/public/theme-bootstrap.js'),
]

// Behavior markers that MUST appear in the bootstrap. If the TS source
// applyThemeToDOM.ts changes its contract, update the bootstrap source and
// these markers in lock-step (then run sync-theme-bootstrap.mjs).
const REQUIRED_MARKERS = [
  // persisted-mode key (mirrors THEME_STORAGE_KEY in packages/theme/src/ThemeMode.ts)
  "'ulticode-theme'",
  // matchMedia media query
  "'(prefers-color-scheme: dark)'",
  // explicit mode branches
  "mode === 'dark'",
  "mode === 'light'",
  // final DOM action
  "html.classList.add('dark')",
  "html.classList.remove('dark')",
]

function sha256(buf) {
  return createHash('sha256').update(buf).digest('hex')
}

function fail(msg) {
  console.error(`✘ ${msg}`)
  process.exit(1)
}

function ok(msg) {
  console.log(`✓ ${msg}`)
}

function read(p) {
  try {
    return readFileSync(p, 'utf8')
  } catch (e) {
    fail(`Cannot read ${p}: ${e.message}`)
  }
}

const sourceBody = read(SOURCE)
const sourceHash = sha256(sourceBody)

// 1. Source must exist and contain every behavior marker.
for (const marker of REQUIRED_MARKERS) {
  if (!sourceBody.includes(marker)) {
    fail(`Missing required marker ${JSON.stringify(marker)} in source — update marker list AND/OR restore it in packages/theme/bootstrap.js`)
  }
}
ok(`Source contains all ${REQUIRED_MARKERS.length} required behavior markers`)

// 2. Each copy must be byte-identical to the source (not just to each other).
for (const copy of COPIES) {
  const body = read(copy)
  const hash = sha256(body)
  if (hash !== sourceHash) {
    console.error(`  ${copy.replace(ROOT + '/', '')} sha256 = ${hash}`)
    console.error(`  packages/theme/bootstrap.js   sha256 = ${sourceHash}`)
    fail(`${copy.replace(ROOT + '/', '')} drifted from the canonical source — run: pnpm sync:theme-bootstrap`)
  }
}
ok(`Both copies are byte-identical to the source (sha256: ${sourceHash.slice(0, 12)}…)`)

console.log('Theme bootstrap sync OK.')
